SELECT total_reservas 
FROM v_resumen_diario 
WHERE fecha = DATE_TRUNC('month', CURRENT_DATE);

SELECT total_ingresos, total_gastos, utilidad_neta 
FROM v_resumen_diario 
WHERE fecha = CURRENT_DATE - INTERVAL '1 day';

SELECT COUNT(*) AS total_reservas
FROM v_reservas_detalle
WHERE EXTRACT(YEAR FROM fecha_reserva) = EXTRACT(YEAR FROM CURRENT_DATE);

SELECT COUNT(*) AS total_reservas
FROM v_reservas_detalle
WHERE segmento = 'grupo' AND fecha_reserva >= DATE_TRUNC('month', CURRENT_DATE);

SELECT COUNT(*) AS total_reservas
FROM v_reservas_detalle
WHERE estado::text LIKE 'completada';

SELECT COUNT(*) AS total_canceladas
FROM reservas
WHERE estado::text LIKE 'cancelada';

SELECT SUM(monto) AS gasto_operativo_total
FROM transacciones_financieras
WHERE tipo::text LIKE 'gasto_operativo%';

SELECT COUNT(*) 
FROM reservas 
WHERE es_temporada_alta = TRUE;

SELECT total_ingresos, total_gastos, utilidad_neta 
FROM v_resumen_diario 
WHERE fecha >= DATE_TRUNC('week', CURRENT_DATE) AND fecha <= DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '6 days';

SELECT total_ingresos, total_gastos, utilidad_neta 
FROM v_resumen_diario 
WHERE fecha = CURRENT_DATE;

SELECT COUNT(*) 
FROM transacciones_financieras 
WHERE tipo::text LIKE 'devolucion%' AND DATE_TRUNC('month', fecha_transaccion) = DATE_TRUNC('month', CURRENT_DATE);

SELECT COUNT(*) 
FROM transacciones_financieras 
WHERE tipo::text LIKE 'ingreso_reserva' AND es_conciliado = FALSE;

SELECT total_ingresos, total_gastos, utilidad_neta 
FROM v_resumen_diario 
WHERE fecha = CURRENT_DATE;

SELECT COUNT(*) AS total_reservas
FROM reservas
WHERE fecha_reserva = CURRENT_DATE;

SELECT total_ingresos, total_gastos, utilidad_neta 
FROM v_resumen_diario 
WHERE fecha = CURRENT_DATE - INTERVAL '1 day';

SELECT SUM(numero_personas) AS total_visitas
FROM reservas
WHERE fecha_reserva >= DATE_TRUNC('month', CURRENT_DATE);
